import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import "./AdminPage.css";

function AdminPage() {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState("dashboard");
  const [slots, setSlots] = useState([]);
  const [bookings, setBookings] = useState([]);
  const [loadingSlots, setLoadingSlots] = useState(true);
  const [loadingBookings, setLoadingBookings] = useState(true);

  useEffect(() => {
    fetch("http://localhost:8081/api/slots/all")
      .then((res) => res.json())
      .then((data) => {
        console.log("Slots API response:", data);
        setSlots(data);
        setLoadingSlots(false);
      })
      .catch((err) => {
        console.error(err);
        setLoadingSlots(false);
      });

    fetch("http://localhost:8081/api/bookings")
      .then((res) => res.json())
      .then((data) => {
        console.log("Bookings API response:", data);
        setBookings(data);
        setLoadingBookings(false);
      })
      .catch((err) => {
        console.error(err);
        setLoadingBookings(false);
      });
  }, []);

  const handleLogout = () => {
    localStorage.clear();
    navigate("/admin-login");
  };

  const renderContent = () => {
    if (activeTab === "dashboard") {
      return (
        <div className="dashboard-content">
          <div className="stat-card">
            <h3>Total Slots</h3>
            <p>{slots.length}</p>
          </div>
          <div className="stat-card">
            <h3>Available Slots</h3>
            <p>{slots.filter((s) => s.isAvailable).length}</p>
          </div>
          <div className="stat-card">
            <h3>Total Bookings</h3>
            <p>{bookings.length}</p>
          </div>
          <pre style={{ maxHeight: 200, overflow: "auto", background: "#eee", padding: 10 }}>
            {JSON.stringify(slots, null, 2)}
          </pre>
        </div>
      );
    }

    if (activeTab === "bookings") {
      if (loadingBookings) return <p>Loading bookings...</p>;
      if (!bookings.length) return <p>No bookings found.</p>;

      return (
        <div>
          <h2>All Bookings</h2>
          <table>
            <thead>
              <tr>
                <th>Booking ID</th>
                <th>Vehicle</th>
                <th>Start</th>
                <th>End</th>
                <th>Cost</th>
                <th>Status</th>
              </tr>
            </thead>
            <tbody>
              {bookings.map((b) => (
                <tr key={b.bookingId || b.id}>
                  <td>{b.bookingId || b.id}</td>
                  <td>{b.vehicleNumber}</td>
                  <td>{new Date(b.startTime).toLocaleString()}</td>
                  <td>{new Date(b.endTime).toLocaleString()}</td>
                  <td>${b.totalCost}</td>
                  <td>{b.status}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      );
    }

    if (activeTab === "facilities") {
      if (loadingSlots) return <p>Loading facilities overview...</p>;
      if (!slots.length) return <p>No slot data available.</p>;

      // Group slots by facilityId and floor
      const facilityMap = {};

      slots.forEach((slot) => {
        const key = `Facility ${slot.facilityId || "N/A"} - Floor ${slot.floor || "N/A"}`;
        if (!facilityMap[key]) {
          facilityMap[key] = { total: 0, available: 0, slots: [] };
        }
        facilityMap[key].total += 1;
        if (slot.isAvailable) {
          facilityMap[key].available += 1;
        }
        facilityMap[key].slots.push(slot);
      });

      return (
        <div>
          <h2>Facilities Overview</h2>
          <table>
            <thead>
              <tr>
                <th>Facility - Floor</th>
                <th>Total Slots</th>
                <th>Available Slots</th>
                <th>Avg Hourly Rate</th>
              </tr>
            </thead>
            <tbody>
              {Object.entries(facilityMap).map(([key, data]) => {
                const avgRate =
                  data.slots.reduce((sum, s) => sum + s.hourlyRate, 0) / data.slots.length;
                return (
                  <tr key={key}>
                    <td>{key}</td>
                    <td>{data.total}</td>
                    <td>{data.available}</td>
                    <td>${avgRate.toFixed(2)}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      );
    }
  };

  return (
    <div className="admin-dashboard">
      <div className="sidebar">
        <h2>Admin Panel</h2>
        <ul>
          <li onClick={() => setActiveTab("dashboard")}>Dashboard</li>
          <li onClick={() => setActiveTab("bookings")}>View Bookings</li>
          <li onClick={() => setActiveTab("facilities")}>Facilities Overview</li>
        </ul>
      </div>

      <div className="main-content">
        <div className="topbar">
          <h1>{activeTab.charAt(0).toUpperCase() + activeTab.slice(1)}</h1>
          <button onClick={handleLogout}>Logout</button>
        </div>
        <div className="content-area">{renderContent()}</div>
      </div>
    </div>
  );
}

export default AdminPage;
